-- 10) POST-CHECKS: the result must equal the independently computed expectation and every invariant must hold (any failure rolls everything back)
-- ---------------------------------------------------------
do $post$
declare
  exp jsonb := $exp$__EXPECT__$exp$::jsonb;
  act jsonb; k text; bad text := ''; c record;
begin
  select * into c from _ctx;
  act := jsonb_build_object(
    'subsystems', (select count(*) from public.subsystems),
    'categories', (select count(*) from public.subsystem_categories),
    'timeline_columns', (select count(*) from public.timeline_columns),
    'timeline_columns_highlighted', (select count(*) from public.timeline_columns where highlight),
    'timeline_milestones', (select count(*) from public.timeline_milestones),
    'recurring_events', (select count(*) from public.recurring_events),
    'tasks', (select count(*) from public.tasks),
    'tasks_complete', (select count(*) from public.tasks where status = 'Complete'),
    'tasks_with_deadline', (select count(*) from public.tasks where deadline is not null),
    'tasks_with_category', (select count(*) from public.tasks where category_id is not null),
    'tasks_with_assignee_raw', (select count(*) from public.tasks where legacy_assignee_raw is not null),
    'purchase_requests', (select count(*) from public.purchase_requests),
    'purchase_items', (select count(*) from public.purchase_request_items),
    'purchase_history', (select count(*) from public.purchase_status_history),
    'exceptions_by_type', (select coalesce(jsonb_object_agg(entity_type, n), '{}'::jsonb) from (select entity_type, count(*) as n from public.migration_exceptions group by 1) x),
    'log_by_entity_status', (select coalesce(jsonb_object_agg(entity_type || ':' || status, n), '{}'::jsonb) from (select entity_type, status, count(*) as n from public.migration_log group by 1, 2) x)
  );
  for k in select jsonb_object_keys(exp) loop
    if act -> k is distinct from exp -> k then bad := bad || format('%s: expected %s but found %s; ', k, exp -> k, act -> k); end if;
  end loop;
  -- invariants
  if (select count(*) from public.notifications) <> 0 then bad := bad || 'NOTIFICATIONS WERE CREATED (import must be silent); '; end if;
  if (select count(*) from public.audit_logs) + (select count(*) from public.task_assignees) + (select count(*) from public.task_comments) + (select count(*) from public.cad_reviews)
     + (select count(*) from public.calendar_events) + (select count(*) from public.milestones) + (select count(*) from public.competition_settings) + (select count(*) from public.member_applications) <> 0 then bad := bad || 'rows appeared in a table the import must not touch; '; end if;
  if (select count(*) from public.tasks where created_by <> c.importer or legacy_id is null or primary_owner_id is not null) <> 0 then bad := bad || 'task attribution/legacy_id/owner wrong; '; end if;
  if (select count(*) from public.timeline_milestones where updated_by <> c.importer) + (select count(*) from public.purchase_requests where requested_by <> c.importer)
     + (select count(*) from public.purchase_status_history where changed_by <> c.importer) <> 0 then bad := bad || 'attribution to the importer is wrong; '; end if;
  if (select count(*) from public.tasks t where t.category_id is not null and not exists (select 1 from public.subsystem_categories sc where sc.id = t.category_id and sc.subsystem_id = t.subsystem_id)) <> 0 then bad := bad || 'a task category does not belong to its subsystem; '; end if;
  if (select count(*) from public.migration_log l where l.entity_type = 'task' and l.status = 'migrated' and not exists (select 1 from public.tasks t where t.id = l.new_id and t.legacy_id = l.legacy_id_or_key)) <> 0 then bad := bad || 'migration_log task rows do not match tasks; '; end if;
  if (select count(*) from public.migration_exceptions where migration_batch_id <> c.batch or resolution_status <> 'unresolved') + (select count(*) from public.migration_log where migration_batch_id <> c.batch) <> 0 then bad := bad || 'batch id / resolution status wrong; '; end if;
  if (select count(*) from public.migration_exceptions where context::text ~* 'leadpin' or raw_value ~* 'leadpin') <> 0 then bad := bad || 'A LEAD PIN REFERENCE IS PRESENT; '; end if;
  -- the owner's profile and the auth user are exactly as before
  if (select count(*) from public.profiles) <> 1 or (select count(*) from auth.users) <> 1 then bad := bad || 'profiles/auth.users count changed; '; end if;
  if (select md5(to_jsonb(p)::text) from public.profiles p where p.id = c.importer) is distinct from c.profile_md5 then bad := bad || 'THE OWNER PROFILE ROW CHANGED; '; end if;
  -- triggers back to normal, schema untouched
  if (select count(*) from pg_trigger t join pg_class cl on cl.oid = t.tgrelid where not t.tgisinternal and t.tgenabled <> 'O' and (cl.relnamespace = 'public'::regnamespace or cl.oid = 'auth.users'::regclass)) <> 0 then bad := bad || 'a trigger is left disabled; '; end if;
  if (select count(*) from pg_trigger t join pg_class cl on cl.oid = t.tgrelid where not t.tgisinternal and cl.relnamespace = 'public'::regnamespace) <> 38 then bad := bad || 'public trigger count <> 38; '; end if;
  if (select count(*) from pg_tables where schemaname = 'public') <> 27 or (select count(*) from pg_policies where schemaname in ('public', 'storage')) <> 88 then bad := bad || 'table/policy count changed; '; end if;
  if (select count(*) from pg_proc p where p.pronamespace = 'public'::regnamespace and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')) <> __FUNCS__ then bad := bad || 'function count changed; '; end if;
  if bad <> '' then
